create extension if not exists "pgcrypto";
create table projects(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null,category text not null,status text not null default 'Idea',priority integer not null default 0,progress integer not null default 0,description text,notion_url text,content_type text,video_style text,script text,thumbnail text,editing text,created_at timestamptz default now());
create table tasks(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,project_id uuid references projects(id) on delete cascade,title text not null,details text,bucket text not null default 'backlog',position integer not null default 0,done boolean not null default false,created_at timestamptz default now());
create table purchases(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,project_id uuid references projects(id) on delete cascade,name text not null,status text not null default 'Need',blocking boolean not null default false,qty numeric not null default 1,cost numeric not null default 0,url text,position integer not null default 0,created_at timestamptz default now());
create table ideas(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,title text not null,category text not null,created_at timestamptz default now());
create table shots(id uuid primary key default gen_random_uuid(),project_id uuid references projects(id) on delete cascade,text text not null,done boolean not null default false,position integer not null default 0);
-- Production: enable RLS on every table and add auth.uid() = user_id policies before cloud deployment.
